INSERT INTO permissions (key, name, category, description) VALUES
  ('crm.leads.view_all', 'View all CRM Leads', 'CRM', 'See every Lead in the permitted companies/branches regardless of owner. Does not widen Opportunities, Accounts or Activities.'),
